import{_ as o,o as s,c as r,af as n}from"./chunks/framework.B28LkSoM.js";const p=JSON.parse('{"title":"Web前端初识","description":"网页由文字图片视频音频超链接组成，前端代码经浏览器内核解析渲染才变成网页；Web 标准三件套 HTML/CSS/JS 分别管结构、表现与行为","frontmatter":{"title":"Web前端初识","published":"2026-09-29T00:00:00.000Z","description":"网页由文字图片视频音频超链接组成，前端代码经浏览器内核解析渲染才变成网页；Web 标准三件套 HTML/CSS/JS 分别管结构、表现与行为","tags":["JavaWeb","前端","Web"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-02-web-frontend-intro.webp","order":2,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/02-Web前端初识.md","filePath":"posts/学习文档/JavaWeb学习笔记/02-Web前端初识.md"}'),a={name:"posts/学习文档/JavaWeb学习笔记/02-Web前端初识.md"};function e(g,t,l,i,d,u){return s(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1790640000000"},[...t[0]||(t[0]=[n('<p>上一篇讲的是&quot;Web 是什么&quot;，这篇往下钻一层：<strong>我们看到的网页由哪几部分组成、背后的本质是什么、前端代码怎么变成用户眼中的网页</strong>，然后把前端的三门语言（HTML/CSS/JS）各自的职责分清楚。</p><h2 id="网页由哪几部分组成" tabindex="-1">网页由哪几部分组成 <a class="header-anchor" href="#网页由哪几部分组成" aria-label="Permalink to &quot;网页由哪几部分组成&quot;">​</a></h2><p>先回答 PPT 上的第一个问题——<strong>网页由哪几部分组成？</strong></p><p>答案：<strong>文字、图片、视频、音频、超链接</strong>…… 这些就是页面上能被看到、能被点的东西。</p><p>再回答第二个问题——<strong>我们看到的网页，背后本质是什么？</strong></p><p>本质是<strong>程序员写的前端代码</strong>（一堆纯文本的标签和文字），浏览器把它&quot;翻译&quot;成你看到的页面：</p><p><img src="https://img.tsh520.cn/file/blog/article/02-%E7%BD%91%E9%A1%B5%E8%83%8C%E5%90%8E%E7%9A%84HTML%E6%BA%90%E7%A0%81.jpg" alt="网页背后的HTML源码"><em>图：网页背后的本质——这就是页面背后的 HTML 源码（可以看到 <code>&lt;h1&gt;</code> 标题、<code>&lt;div class=&quot;info&quot;&gt;</code>、<code>&lt;span&gt;</code> 这类标签，页面上的每段文字都对应其中一段代码）</em></p><h2 id="前端代码怎么变成用户眼中的网页" tabindex="-1">前端代码怎么变成用户眼中的网页 <a class="header-anchor" href="#前端代码怎么变成用户眼中的网页" aria-label="Permalink to &quot;前端代码怎么变成用户眼中的网页&quot;">​</a></h2><p>第三个问题：<strong>前端代码如何转换成用户眼中的网页？</strong></p><ul><li>程序员写的是<strong>前端代码</strong>；</li><li>通过<strong>浏览器</strong>把代码转换成用户看到的网页；</li><li>浏览器里<strong>对代码进行解析渲染</strong>的部分，称为<strong>浏览器内核</strong>。</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">重要</p><p><strong>不同浏览器，内核不同</strong>，对同一份前端代码解析的效果<strong>可能会存在差异</strong>。这就是&quot;前端要做浏览器兼容&quot;这件事的根源——同一份代码在 Chrome 和 Safari 里可能长得不完全一样。</p></div><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>PPT 上没展开写具体的内核对应关系，这里补一句常识方便理解：Chrome、新版 Edge 用 <strong>Blink</strong>，Safari 用 <strong>WebKit</strong>，Firefox 用 <strong>Gecko</strong>，老 IE 用 <strong>Trident</strong>。记住规律就行——<strong>内核决定解析渲染的结果</strong>，写页面时尽量按标准写，别依赖某个浏览器独有的行为。</p></div><h2 id="web-标准-三件套各管什么" tabindex="-1">Web 标准：三件套各管什么 <a class="header-anchor" href="#web-标准-三件套各管什么" aria-label="Permalink to &quot;Web 标准：三件套各管什么&quot;">​</a></h2><p><strong>Web 标准</strong>也称<strong>网页标准</strong>，由一系列的标准组成，大部分由 <strong>W3C</strong>（World Wide Web Consortium，<strong>万维网联盟</strong>）负责制定。它有三个组成部分：</p><table tabindex="0"><thead><tr><th>部分</th><th>负责</th><th>管的范围</th></tr></thead><tbody><tr><td><strong>HTML</strong></td><td>网页的<strong>结构</strong></td><td>页面元素和内容</td></tr><tr><td><strong>CSS</strong></td><td>网页的<strong>表现</strong></td><td>页面元素的外观、位置等页面样式（如颜色、大小）</td></tr><tr><td><strong>JavaScript</strong></td><td>网页的<strong>行为</strong></td><td>交互效果</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p>一个经典的类比：HTML 是<strong>毛坯房</strong>（墙和房间＝结构），CSS 是<strong>装修</strong>（刷漆、摆放家具＝表现），JavaScript 是<strong>电器</strong>（灯开关、门铃＝行为）。房子没装修也能住，但不好看；没有电器，灯就不会亮——三者缺一不可，但职责绝不重叠。</p></div><h2 id="前端课程安排" tabindex="-1">前端课程安排 <a class="header-anchor" href="#前端课程安排" aria-label="Permalink to &quot;前端课程安排&quot;">​</a></h2><p>前端这块在整门课里拆成两段（对应课程导学里的 part1 和 part5）：</p><table tabindex="0"><thead><tr><th>阶段</th><th>学什么</th><th>天数</th></tr></thead><tbody><tr><td><strong>Web 前端基础</strong></td><td>HTML + CSS + JS，Vue3 + Ajax</td><td>2 天</td></tr><tr><td><strong>Web 前端实战</strong></td><td>Vue 工程化 + ElementPlus + Vue3 案例（Tlias 案例）</td><td>4 天</td></tr></tbody></table><p>也就是说：<strong>基础阶段</strong>把 HTML/CSS/JS 和 Vue3 的基本用法过一遍，<strong>实战阶段</strong>再用工程化的方式（Vue 脚手架 + ElementPlus 组件库）做一个完整的前端项目，最后和后端接口对接。</p><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>PPT 里这张课程地图上，&quot;Vue 工程化 + ElementPlus + Vue3 案例&quot;这一框出现过 <strong>3 天</strong>和 <strong>4 天</strong>两种写法（同一页动画的两个状态）。以课程导学和后一页为准：<strong>4 天</strong>。</p></div><h2 id="小结-前端初识回顾" tabindex="-1">小结（前端初识回顾） <a class="header-anchor" href="#小结-前端初识回顾" aria-label="Permalink to &quot;小结（前端初识回顾）&quot;">​</a></h2><p>PPT 的这一节最后用一页问答做了收尾，三个问题连起来就是这一节的主线：</p><table tabindex="0"><thead><tr><th>问题</th><th>答案</th></tr></thead><tbody><tr><td>我们看到的网页由什么组成？</td><td><strong>文字、图片、视频、音频、超链接</strong>等</td></tr><tr><td>看到的网页背后本质是什么？</td><td><strong>程序员写的前端代码</strong>，由浏览器解析渲染出来</td></tr><tr><td>前端代码如何转换成用户眼中的网页？</td><td>浏览器对代码进行<strong>解析渲染</strong>，负责这部分工作的叫<strong>浏览器内核</strong>（不同浏览器内核不同，效果可能有差异）</td></tr><tr><td>一个网页由哪几个部分组成？各自的职责？</td><td><strong>HTML</strong> 负责网页的<strong>结构</strong>；<strong>CSS</strong> 负责网页的<strong>表现</strong>；<strong>JavaScript</strong> 负责网页的<strong>行为</strong>（动作）</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/posts/编程学习/javaweb学习笔记/01-javaweb课程导学/">JavaWeb课程导学</a></li><li><a href="/posts/编程学习/javaweb学习笔记/03-html快速入门/">HTML快速入门</a></li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><h3 id="一、知识回顾-读完直接做下面的实践题" tabindex="-1">一、知识回顾（读完直接做下面的实践题） <a class="header-anchor" href="#一、知识回顾-读完直接做下面的实践题" aria-label="Permalink to &quot;一、知识回顾（读完直接做下面的实践题）&quot;">​</a></h3><ol><li>网页由 <strong>文字、图片、视频、音频、超链接</strong> 等部分组成；网页背后的本质是<strong>程序员写的前端代码</strong></li><li>前端代码通过<strong>浏览器</strong>转换成用户看到的网页；浏览器里对代码进行<strong>解析渲染</strong>的部分称为<strong>浏览器内核</strong></li><li><strong>不同浏览器内核不同</strong>，对相同的前端代码<strong>解析的效果可能会存在差异</strong></li><li><strong>Web 标准</strong>（网页标准）由一系列标准组成，大部分由 <strong>W3C</strong>（World Wide Web Consortium，<strong>万维网联盟</strong>）负责制定</li><li>Web 标准的三个组成部分及其职责：<strong>HTML</strong> 负责网页的<strong>结构</strong>（页面元素和内容）、<strong>CSS</strong> 负责网页的<strong>表现</strong>（外观、位置等样式，如颜色、大小）、<strong>JavaScript</strong> 负责网页的<strong>行为</strong>（交互效果）</li><li>前端课程分两段：<strong>Web 前端基础</strong>（HTML + CSS + JS，Vue3 + Ajax，<strong>2 天</strong>）和 <strong>Web 前端实战</strong>（Vue 工程化 + ElementPlus + Vue3 案例，<strong>4 天</strong>）</li><li>记忆类比：HTML＝<strong>毛坯房</strong>（结构）、CSS＝<strong>装修</strong>（表现）、JavaScript＝<strong>电器</strong>（行为）</li><li>浏览器兼容问题的根源是<strong>内核不同</strong>：Chrome/新版 Edge 用 <strong>Blink</strong>、Safari 用 <strong>WebKit</strong>、Firefox 用 <strong>Gecko</strong>（PPT 未展开，属补充常识）</li></ol><h3 id="二、概念自测" tabindex="-1">二、概念自测 <a class="header-anchor" href="#二、概念自测" aria-label="Permalink to &quot;二、概念自测&quot;">​</a></h3><ul><li><p>[ ] <strong>2-1 一个网页由哪几个部分组成？各自的职责是什么？</strong> 要求：三部分都要说出&quot;名字 + 一句话职责&quot;，不要只说缩写。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：想想&quot;结构、表现、行为&quot;这六个字分别对哪门语言 <strong>二级 · 角度</strong>：内容归谁管？颜色大小位置归谁管？点击后的反应归谁管？</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-1</strong> 三部分：<strong>HTML</strong> 负责网页的结构（页面元素和内容）；<strong>CSS</strong> 负责网页的表现（元素的外观、位置等样式，如颜色、大小）；<strong>JavaScript</strong> 负责网页的行为（交互效果）。</p></details></li><li><p>[ ] <strong>2-2 同样一段 HTML，在 Chrome 和 Safari 里看起来不太一样，可能是哪一环出了问题？</strong> 要求：用&quot;内核&quot;这个词解释，并说出为什么这是前端必须考虑的事。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：你写的前端代码是交给谁&quot;翻译&quot;的？不同的翻译者，结果会一样吗</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-2</strong> 出在<strong>浏览器内核</strong>上：浏览器对代码进行<strong>解析渲染</strong>的部分叫内核，<strong>不同浏览器的内核不同</strong>，所以同一份前端代码的解析效果可能存在差异。写页面时按 <strong>Web 标准</strong>来写、别依赖某个浏览器的私有行为，才能让页面在各浏览器里都正常。</p></details></li><li><p>[ ] <strong>2-3 判断并说明理由：只要 HTML 写得漂亮，页面就好看、也点得动。</strong> 要求：分别指出&quot;好看&quot;和&quot;点得动&quot;归谁管。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：把&quot;好看&quot;和&quot;点得动&quot;分别对到三件套的职责上——结构和样式是两回事</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-3</strong> 不对。HTML 只管<strong>结构</strong>（页面元素和内容）；&quot;好看&quot;要交给 <strong>CSS</strong>（表现：颜色、大小、位置）；&quot;点得动、有反应&quot;要交给 <strong>JavaScript</strong>（行为：交互效果）。三件套各管一摊，谁也不能代替谁。</p></details></li><li><p>[ ] <strong>2-4 如果老师只给你一张网页截图，你能从截图里分出哪部分可能是 HTML、哪部分可能是 CSS 做的吗？</strong> 要求：各举 1 个本页图片里能看到的具体例子。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：先分清&quot;内容&quot;和&quot;样式&quot;：文字、图片、链接属于内容；字号、颜色、位置属于样式</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-4</strong> 能。<strong>内容本身是 HTML</strong>——新闻标题文字、正文段落、图片、&quot;央视网&quot;这类链接；<strong>这些内容长什么样是 CSS</strong>——标题的字号、正文的颜色（灰）、行高、页面的左右留白与居中（截图里标题的字号明显大于正文、正文字色偏灰）。属于<strong>行为</strong>的（点击播放、点赞变色）则要看 JavaScript。</p></details></li></ul>',31)])])}const b=o(a,[["render",e]]);export{p as __pageData,b as default};
